Python example:
from redwood_sdk.function_helpers import coerce_and_validate, invoke_with_retry, StreamReassembler

# function schema (example)
schema = {
  "name": "create_invoice",
  "params": {
    "type": "object",
    "properties": {
      "amount": {
        "type": "number"
      },
      "currency": {
        "type": "string", "default": "USD"
      }
    },
    "required": ["amount"]
  }
}

# tolerant validation + coercion
payload = {
  "amount": "4999",  # string from model, should coerce to number
  "currency": "usd"  # fuzzy enum match to USD
}
clean = coerce_and_validate(schema, payload, policy={
  "coerce_numbers": True,
  "coerce_enums": "case_insensitive",
  "default_fill": True
})

# invoke with automatic retry and idempotency
resp = invoke_with_retry(
  client.call_function,
  name=schema['name'],
  params=clean,
  max_attempts=3,
  idempotency_key="invoice-create-123"
)

# streaming: reassemble partial JSON and validate incrementally
reasm = StreamReassembler(schema)
for chunk in client.stream_function_chunks("create_invoice", params=clean):
    reasm.feed(chunk)
    if reasm.partial_valid():
        # optimistic processing (metrics/tracing)
        pass
final = reasm.finish()
