import { coerceAndValidate, invokeWithRetry, StreamReassembler } from '@redwood/sdk-function-helpers'

const schema = { /* same logical schema as python */ }
const payload = { amount: '4999', currency: 'usd', extra: 'ignored' }
const clean = coerceAndValidate(schema, payload, { coerceNumbers: true, coerceEnums: 'case_insensitive', defaultFill: true })

const response = await invokeWithRetry(client.callFunction, { name: schema.name, params: clean, maxAttempts: 4, idempotencyKey: 'invoice-create-123' })

// streaming usage
const reasm = new StreamReassembler(schema)
for await (const chunk of client.streamFunctionChunks('create_invoice', { params: clean })) {
  reasm.feed(chunk)
  if (reasm.partialValid()) {
    // emit telemetry
  }
}
const final = reasm.finish()
Go example:
package main
import (
  "context"
  "fmt"
  "github.com/redwood/sdk/functionhelpers"
)

func main() {
  schema := map[string]interface{}{} // simplified
  payload := map[string]interface{}{
    "amount": "4999",
  }

  clean, err := functionhelpers.CoerceAndValidate(schema, payload, functionhelpers.Policy{CoerceNumbers:true, CoerceEnums: functionhelpers.CaseInsensitive})
  if err != nil {
    panic(err)
  }

  resp, err := functionhelpers.InvokeWithRetry(context.Background(), client.CallFunction, functionhelpers.InvokeOpts{ Name: "create_invoice", Params: clean, MaxAttempts: 3, IdempotencyKey: "invoice-create-123" })
  if err != nil {
    panic(err)
  }
  fmt.Println(resp)
}
